<?php $this->view('page_components/header'); ?>
<div class="page-heading d-flex justify-content-between align-items-start gap-3"><div><h3>Szczegóły wiadomości #<?= (int)$message['id'] ?></h3><p class="text-subtitle text-muted mb-0">Niezmienna kopia przygotowanej korespondencji.</p></div><a class="btn btn-outline-secondary" href="<?= ROOT ?>/communication/messages">Wróć do listy</a></div>
<section class="section"><div class="card"><div class="card-body"><dl class="row mb-4"><dt class="col-sm-3">Odbiorca</dt><dd class="col-sm-9"><?= htmlspecialchars($message['recipient_email'], ENT_QUOTES, 'UTF-8') ?></dd><dt class="col-sm-3">Status</dt><dd class="col-sm-9"><?= htmlspecialchars($message['status'], ENT_QUOTES, 'UTF-8') ?> · próby: <?= (int)$message['attempts'] ?></dd><dt class="col-sm-3">Temat</dt><dd class="col-sm-9"><?= htmlspecialchars($message['subject_text'], ENT_QUOTES, 'UTF-8') ?></dd><?php if (!empty($message['error_message'])): ?><dt class="col-sm-3 text-danger">Błąd</dt><dd class="col-sm-9 text-danger"><?= htmlspecialchars($message['error_message'], ENT_QUOTES, 'UTF-8') ?></dd><?php endif; ?></dl><?php if (!empty($message['attachments'])): ?><h6>Załączniki</h6><ul><?php foreach ($message['attachments'] as $attachment): ?><li><?= htmlspecialchars($attachment['filename'], ENT_QUOTES, 'UTF-8') ?> <span class="text-muted">(<?= (int)$attachment['size_bytes'] ?> B)</span></li><?php endforeach; ?></ul><?php endif; ?><label class="form-label">Treść wysłana</label><pre class="border rounded p-3 bg-light mb-0" style="white-space:pre-wrap"><?= htmlspecialchars($message['body_text'], ENT_QUOTES, 'UTF-8') ?></pre></div></div>
<?php if (!empty($message['incoming'])): ?><div class="card mt-4"><div class="card-body"><h5>Odpowiedzi</h5><?php foreach ($message['incoming'] as $reply): ?><article class="border-top pt-3 mt-3"><div class="small text-muted"><?= htmlspecialchars($reply['received_at'], ENT_QUOTES, 'UTF-8') ?> · <?= htmlspecialchars($reply['sender_email'], ENT_QUOTES, 'UTF-8') ?></div><div class="fw-semibold"><?= htmlspecialchars($reply['subject_text'] ?? '', ENT_QUOTES, 'UTF-8') ?></div><pre class="mb-0 mt-2" style="white-space:pre-wrap"><?= htmlspecialchars($reply['body_text'], ENT_QUOTES, 'UTF-8') ?></pre></article><?php endforeach; ?></div></div><?php endif; ?></section>
